import { FieldError, SwitchButton, SwitchField, Text } from "react-aria-components";
import type {
  SwitchFieldProps as AriaSwitchFieldProps,
  ValidationResult,
} from "react-aria-components";
import type { ReactNode, Ref } from "react";
import "./Switch.css";

// Category A — borrows React Aria's SwitchField (validation-capable) + SwitchButton split.
// SwitchField is the <div> wrapper that owns validation state + the description/error slots;
// SwitchButton is the clickable <label> (track + thumb + label text). This split (not the
// deprecated single <Switch>) is what lets a Switch participate in form validation — the
// deprecated SwitchProps Omits isInvalid/isRequired/validate.
export type SwitchSize = "small" | "medium" | "large";

export interface SwitchProps
  extends Omit<AriaSwitchFieldProps, "className" | "children"> {
  /**
   * Size axis: the track, thumb, hit area, row and the label's type role together.
   *
   * @default "medium"
   */
  size?: SwitchSize;
  /**
   * The thumb's outline: `circle` a round knob, `rectangle` a capsule longer along the track.
   *
   * @default "circle"
   */
  thumbShape?: "rectangle" | "circle";
  /**
   * Which side of the switch its label sits: `end` after it, `start` before it, the label leading a
   * toggle that closes a row (a filter row's 「페이백 포함 요금」, a settings line). The helper lines
   * follow the label's axis either way.
   *
   * @default "end"
   */
  labelPlacement?: "end" | "start";
  /** Switch label content. */
  children?: ReactNode;
  /** Helper text below the switch. */
  description?: string;
  /** Message shown when validation fails. */
  errorMessage?: string | ((v: ValidationResult) => string);
  /** Additional class (optional). sd-switch is always preserved. */
  className?: string;
  /** Forwarded to the underlying wrapper <div> DOM node (the input uses inputRef). */
  ref?: Ref<HTMLDivElement>;
}

export function Switch({
  size = "medium",
  thumbShape = "circle",
  labelPlacement = "end",
  children,
  description,
  errorMessage,
  className,
  ...props
}: SwitchProps) {
  return (
    <SwitchField
      {...props}
      data-size={size}
      data-thumb-shape={thumbShape}
      className={className ? `sd-switch ${className}` : "sd-switch"}
    >
      {/* The label's type role sits on the <label> itself, so the track reads the label's own line
          box (`1lh`) to centre on its first line, as Checkbox's box does. */}
      <SwitchButton data-label-placement={labelPlacement} className={`sd-switch__button sd-type-body-${size}`}>
        <span aria-hidden="true" className="sd-switch__track">
          <span className="sd-switch__thumb" />
        </span>
        <span className="sd-switch__label">{children}</span>
      </SwitchButton>
      {description && (
        <Text slot="description" data-label-placement={labelPlacement} className={`sd-switch__description sd-type-caption-${size}`}>
          {description}
        </Text>
      )}
      <FieldError data-label-placement={labelPlacement} className={`sd-switch__error sd-type-caption-${size}`}>{errorMessage}</FieldError>
    </SwitchField>
  );
}

/* SwitchField wrapper (<div>): the field column — the clickable button on top, then the
   optional description / error. Validation + disabled state live here (RAC emits them on the
   field div); interaction state lives on __button below. */
.sd-switch {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--sd-switch-field-gap);
}
/* size — relayed from the root as `-current` intermediates (contract §6 rule 5), as Checkbox does.
   Medium is the old single set. */
.sd-switch[data-size="small"] {
  --sd-switch-gap-current: var(--sd-switch-gap-small);
  --sd-switch-padding-block-current: var(--sd-switch-padding-block-small);
  --sd-switch-state-layer-spread-current: var(--sd-switch-state-layer-spread-small);
  --sd-switch-track-width-current: var(--sd-switch-track-width-small);
  --sd-switch-track-height-current: var(--sd-switch-track-height-small);
  --sd-switch-thumb-size-current: var(--sd-switch-thumb-size-small);
  --sd-switch-thumb-rectangle-width-current: var(--sd-switch-thumb-width-small);
  --sd-switch-thumb-translate-selected-current: var(--sd-switch-thumb-translate-selected-small);
  --sd-switch-field-inset-current: var(--sd-switch-field-inset-small);
}
.sd-switch[data-size="medium"] {
  --sd-switch-gap-current: var(--sd-switch-gap-medium);
  --sd-switch-padding-block-current: var(--sd-switch-padding-block-medium);
  --sd-switch-state-layer-spread-current: var(--sd-switch-state-layer-spread-medium);
  --sd-switch-track-width-current: var(--sd-switch-track-width-medium);
  --sd-switch-track-height-current: var(--sd-switch-track-height-medium);
  --sd-switch-thumb-size-current: var(--sd-switch-thumb-size-medium);
  --sd-switch-thumb-rectangle-width-current: var(--sd-switch-thumb-width-medium);
  --sd-switch-thumb-translate-selected-current: var(--sd-switch-thumb-translate-selected-medium);
  --sd-switch-field-inset-current: var(--sd-switch-field-inset-medium);
}
.sd-switch[data-size="large"] {
  --sd-switch-gap-current: var(--sd-switch-gap-large);
  --sd-switch-padding-block-current: var(--sd-switch-padding-block-large);
  --sd-switch-state-layer-spread-current: var(--sd-switch-state-layer-spread-large);
  --sd-switch-track-width-current: var(--sd-switch-track-width-large);
  --sd-switch-track-height-current: var(--sd-switch-track-height-large);
  --sd-switch-thumb-size-current: var(--sd-switch-thumb-size-large);
  --sd-switch-thumb-rectangle-width-current: var(--sd-switch-thumb-width-large);
  --sd-switch-thumb-translate-selected-current: var(--sd-switch-thumb-translate-selected-large);
  --sd-switch-field-inset-current: var(--sd-switch-field-inset-large);
}
/* thumbShape — a circle is as long as it is tall (the default); a rectangle stretches into a capsule
   along the track. Declared after the size rules so it reads the size's own capsule length. */
.sd-switch {
  --sd-switch-thumb-width-current: var(--sd-switch-thumb-size-current);
}
.sd-switch[data-thumb-shape="rectangle"] {
  --sd-switch-thumb-width-current: var(--sd-switch-thumb-rectangle-width-current);
}
.sd-switch[data-disabled] {
  /* dim the whole field once at the wrapper (button opacity would miss description/error). */
  opacity: var(--sd-state-disabled);
}

/* SwitchButton (<label>): the clickable interactive region — track + label, with the padded,
   rounded hover/press area (matches Checkbox/Radio, ADR-0009 ghost overlay). Rest transparent. */
.sd-switch__button {
  --sd-switch-track-background-current: var(--sd-switch-track-background);
  --sd-switch-track-border-current: var(--sd-switch-track-border);
  --sd-switch-thumb-transform-current: translateX(0);
  /* the hover/pressed state-layer + focus ring hug the TRACK (pill), never the label. Set per
     state here; read on the track's ::before below (§5, combinator-free). */
  --sd-switch-state-layer-current: transparent;
  --sd-switch-ring-current: 0 0 0 0 transparent;
  --sd-switch-ring-outline-current: none;

  display: inline-flex;
  /* top-align the track to a wrapping label's FIRST line (see Checkbox). */
  align-items: flex-start;
  gap: var(--sd-switch-gap-current);
  padding-block: var(--sd-switch-padding-block-current);
  padding-inline: var(--sd-switch-padding-inline);
  border-radius: var(--sd-switch-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: var(--sd-switch-background);
  color: var(--sd-switch-label-foreground);
  cursor: pointer;
  user-select: none;
  position: relative;
  outline: none;
}
.sd-switch__button[data-hovered] {
  --sd-switch-track-border-current: var(--sd-switch-track-border-hover);
  --sd-switch-state-layer-current: var(--sd-state-hover);
}
.sd-switch__button[data-selected] {
  --sd-switch-track-background-current: var(--sd-switch-track-background-selected);
  --sd-switch-track-border-current: var(--sd-switch-track-border-selected);
  /* A capsule thumb is longer than the circle the translate was measured for, so it travels that much less. */
  --sd-switch-thumb-transform-current: translateX(calc(var(--sd-switch-thumb-translate-selected-current) - (var(--sd-switch-thumb-width-current) - var(--sd-switch-thumb-size-current))));
}
.sd-switch__button[data-pressed] {
  --sd-switch-state-layer-current: var(--sd-state-pressed);
}
.sd-switch__button[data-disabled] {
  cursor: not-allowed;
}
.sd-switch__button[data-readonly] {
  /* read-only: still focusable/valid, just not togglable — signal via cursor (RAC emits
     data-readonly on the button). */
  cursor: default;
}
.sd-switch__button[data-focus-visible] {
  --sd-switch-ring-current: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  --sd-switch-ring-outline-current: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-switch__track {
  position: relative;
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  /* centre the track on the label's first line: (the label's own line box − track height) / 2.
     `1lh` reads the role class on the <label>, so it holds at every size, brand and usage context;
     the `1.5rem` it replaces was the default brand's medium line box only (see Checkbox). */
  margin-block-start: calc((1lh - var(--sd-switch-track-height-current)) / 2);
  width: var(--sd-switch-track-width-current);
  height: var(--sd-switch-track-height-current);
  padding: var(--sd-switch-track-padding);
  background: var(--sd-switch-track-background-current);
  border: var(--sd-switch-track-border-width) solid var(--sd-switch-track-border-current);
  border-radius: var(--sd-switch-track-radius);
  corner-shape: round;
  transition:
    background-color var(--sd-duration-moderate) var(--sd-easing-standard),
    border-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
/* Interaction state-layer + focus ring as a rounded shape hugging the track (ADR-0009), extending
   `state-layer-spread` beyond the pill on every side. Translucent hover/pressed tint reads as a
   halo around the track (under the thumb, over the track fill); the label is never covered. Its
   height also clears the WCAG 2.5.8 (24px) target the old transparent hit-area provided. */
.sd-switch__track::before {
  content: "";
  position: absolute;
  inset: calc(-1 * var(--sd-switch-state-layer-spread-current));
  border-radius: var(--sd-switch-track-radius);
  corner-shape: round;
  background: var(--sd-switch-state-layer-current);
  box-shadow: var(--sd-switch-ring-current);
  outline: var(--sd-switch-ring-outline-current);
  pointer-events: none;
  transition:
    background-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
}

/* thumb — the knob. Its colour is INK ON THE TRACK, so it is a theme-invariant on-colour ink and
   NOT `surface.inset` (the recessed field surface, which flips with the theme and left three of the
   four track/theme combinations under 1.4.11's 3:1 — light unselected was 1.00:1, the thumb being
   the exact colour of its track and outlined only by the shadow). The border is what makes the knob
   identifiable on the UNSELECTED track, where a light ink alone is 1.28:1 in light theme; it stays
   on in both states because it is harmless over the brand track and a border that blinks in and out
   with `[data-selected]` reads as a glitch while the thumb slides. `box-sizing: border-box` keeps
   the knob the size the token says — the border must not grow it, or the travel distance
   (`thumb.translate.selected`) no longer lands it flush against the track's padding. */
.sd-switch__thumb {
  box-sizing: border-box;
  width: var(--sd-switch-thumb-width-current);
  height: var(--sd-switch-thumb-size-current);
  background: var(--sd-switch-thumb-background);
  border: var(--sd-switch-thumb-border-width) solid var(--sd-switch-thumb-border);
  border-radius: var(--sd-switch-thumb-radius);
  corner-shape: round;
  box-shadow: var(--sd-switch-thumb-shadow);
  transform: var(--sd-switch-thumb-transform-current);
  transition: transform var(--sd-duration-moderate) var(--sd-easing-standard);
}

.sd-switch__label {
  color: var(--sd-switch-label-foreground);
}
/* start: the label leads and the track closes the row. */
.sd-switch__button[data-label-placement="start"] {
  flex-direction: row-reverse;
}

/* The helper lines start on the label's axis, as Checkbox's: the button's inline padding, the
   track, then the gap between track and label, from the tokens the button spends. */
.sd-switch__description,
.sd-switch__error {
  padding-inline-start: var(--sd-switch-field-inset-current);
}
/* With the label first, its axis is the button's own inline padding, which is the label's one text
   inset: the label carries no role of its own (the button does), as Checkbox's. */
.sd-switch__description[data-label-placement="start"],
.sd-switch__error[data-label-placement="start"] {
  padding-inline-start: var(--sd-switch-field-inset-start);
}

.sd-switch__description {
  color: var(--sd-switch-description-foreground);
}

.sd-switch__error {
  color: var(--sd-switch-error-foreground);
}

@media (prefers-reduced-motion: reduce) {
  .sd-switch__thumb {
    transition: none;
  }
}
